package com.project7.localmanager;
import android.content.Context;import android.content.res.AssetManager;import android.system.Os;
import java.io.*;import java.lang.reflect.*;import java.nio.*;import java.nio.file.*;import java.security.*;import java.util.*;
/** Actual stock friendship engine, Gateway and atomic Store; synthetic BSON only. */
public final class FriendEngineHost {
 static int checks;static final String ACCOUNT="friend_host";static final byte[]ID=new byte[12];
 static void check(boolean b,String m){if(!b)throw new AssertionError(m);checks++;}
 static int value(byte[]b,String k){Integer n=BsonLite.intValue(b,k);return n==null?0:n;}
 static byte[]seed(){return BsonLite.withRequiredClientDefaults(BsonLite.document("uid",7,"level",110,"money",1000,"friendCoin",10000,"newFriendCoin",10000,"unknownFriendScalar",123456,"heromgr",BsonLite.document("hrs",new ArrayList<>()),"inv",BsonLite.document("items",new ArrayList<>(),"mc",100),"ldd",BsonLite.document("ct",0,"iof",false,"fd",false,"hfp",BsonLite.EMPTY_DOCUMENT)));}
 static byte[]md5(String s)throws Exception{return MessageDigest.getInstance("MD5").digest(s.getBytes("UTF-8"));}
 static LocalResourceEngine.Reply reply(LocalResourceEngine.Result r,String n){for(LocalResourceEngine.Reply q:r.replies)if(q.method.equals(n))return q;throw new AssertionError("missing "+n);}
 static List<ProtoLite.EntityMessage>frames(byte[]wire)throws Exception{List<ProtoLite.EntityMessage>r=new ArrayList<>();ByteBuffer b=ByteBuffer.wrap(wire).order(ByteOrder.LITTLE_ENDIAN);while(b.hasRemaining()){int n=b.getInt();check(b.getShort()==5,"original opcode5");byte[]p=new byte[n-2];b.get(p);r.add(ProtoLite.parseEntityMessage(p));}return r;}
 static void fixture(String name,List<ProtoLite.EntityMessage>f)throws Exception{System.out.print("FRIEND_FIXTURE "+name+" ");List<String>parts=new ArrayList<>();for(ProtoLite.EntityMessage m:f){boolean keep=false;for(String n:new String[]{"replyLuckyDrawFriendCard","replyLuckyDrawFriendLianChouCard","replyLuckyDrawNewFriendCard","replyLuckyDrawNewFriendLianChouCard","updateFriendDraw","updateCurTimesDay","serverCallbackCarrier"})if(Arrays.equals(m.methodMd5,md5(n)))keep=true;if(keep)parts.add(Base64.getEncoder().encodeToString(m.methodMd5)+":"+Base64.getEncoder().encodeToString(m.parameters));}System.out.println(String.join(",",parts));}
 public static void main(String[]args)throws Exception{
  Path root=Files.createTempDirectory("p7-friend-synthetic-");try{
   Context context=new Context(root.toFile(),new AssetManager(new File(args[0]),new File(args[1]),new File(args[2]),new File(args[3]),new File(args[4])));CoreDrawPolicy.prepare(context);HistoryDrawPolicy.prepare(context);HistoryFurniturePolicy.prepare(context);
   LocalResourceCatalog catalog;try(InputStream in=new FileInputStream(args[1])){catalog=new LocalResourceCatalog(in);}
   check(catalog.friendDrops.containsKey(-99)&&catalog.friendDrops.containsKey(99)&&catalog.friendDrops.containsKey(131),"fixed actual three friend distributions");
   // Every positive fixed leaf takes original card -> original reveal, not a surrogate grant.
   Map<String,Integer>kinds=new TreeMap<>();for(int pool:new int[]{-99,99,131})for(LocalResourceCatalog.Drop d:catalog.friendDrops.get(pool)){if(d.weight<=0)continue;LocalResourceEngine.Result r=new LocalResourceEngine.Result(seed());byte[]card=LocalFriendDrawEngine.card(d,0);LocalDrawEngine.reveal(r,catalog,card);check(value(r.profile,"unknownFriendScalar")==123456,"leaf preserves unknown field");kinds.put(d.kind,kinds.getOrDefault(d.kind,0)+1);}
   System.out.println("FRIEND_FIXED_LEAF_KINDS "+kinds);
   Path dir=root.resolve("profiles");Files.createDirectories(dir);Path file=dir.resolve(ACCOUNT+".bson");Files.write(file,seed());LocalProfileStore store=new LocalProfileStore(context);
   LocalGatewayServer gateway=new LocalGatewayServer(0,null,store,new LocalTutorialStore(context),null,null,null,null,(s,m)->{});
   Method complete=LocalGatewayServer.class.getDeclaredMethod("completeEmptyCallback",OutputStream.class,byte[].class,byte[].class,String.class);complete.setAccessible(true);
   Method dispatch=LocalGatewayServer.class.getDeclaredMethod("handleResourceRpc",OutputStream.class,byte[].class,byte[].class,byte[].class,String.class);dispatch.setAccessible(true);
   String[]names={"requestLuckyDrawFriendCard","requestLuckyDrawFriendLianChouCard","requestLuckyDrawNewFriendCard","requestLuckyDrawNewFriendLianChouCard"};
   for(int i=0;i<names.length;i++){
    String name=names[i];byte[]before=Files.readAllBytes(file);int renames=Os.renames;ByteArrayOutputStream out=new ByteArrayOutputStream();check(Boolean.TRUE.equals(dispatch.invoke(gateway,out,ID,md5(name),BsonLite.document("_cbid_",200+i),ACCOUNT)),"actual Gateway handles "+name);complete.invoke(gateway,out,ID,BsonLite.document("_cbid_",200+i),"resourceRpc");List<ProtoLite.EntityMessage>f=frames(out.toByteArray());byte[]typed=null;for(ProtoLite.EntityMessage q:f)if(Arrays.equals(q.methodMd5,md5(name.replace("request","reply"))))typed=q.parameters;check(typed!=null&&Boolean.TRUE.equals(BsonLite.boolValue(typed,"st")),"typed success "+name);
    byte[]after=Files.readAllBytes(file);check(Os.renames==renames+1,"one actual atomic commit");check(value(after,"unknownFriendScalar")==123456,"unknown scalar across Gateway/Store");String coin=name.contains("NewFriend")?"newFriendCoin":"friendCoin";int cost=i==0?0:(name.contains("LianChou")?2000:200);check(value(before,coin)-value(after,coin)==cost,"stock cost/first free");fixture("success_"+i,f);
   }
   byte[]persisted=Files.readAllBytes(file);LocalResourceEngine.Result reloaded=new LocalProfileStore(context).updateResources(ACCOUNT,names[0],BsonLite.EMPTY_DOCUMENT);check(value(persisted,"friendCoin")-value(reloaded.profile,"friendCoin")==200,"restart cannot regain first free");check(value(BsonLite.documentValue(reloaded.profile,"ldd"),"q7FriendTotal")==12,"cumulative friend total survives restart");
   byte[]empty=BsonLite.withProfileInt(BsonLite.withProfileInt(seed(),"friendCoin",0),"newFriendCoin",0);empty=LocalDrawDailyEngine.refresh(empty,LocalStoryEnvironment.now());empty=BsonLite.withProfileDocument(empty,"ldd",BsonLite.withProfileBool(BsonLite.documentValue(empty,"ldd"),"fd",true));
   for(int i=0;i<names.length;i++){Files.write(file,empty);ByteArrayOutputStream out=new ByteArrayOutputStream();dispatch.invoke(gateway,out,ID,md5(names[i]),BsonLite.document("_cbid_",300+i),ACCOUNT);complete.invoke(gateway,out,ID,BsonLite.document("_cbid_",300+i),"resourceRpc");List<ProtoLite.EntityMessage>f=frames(out.toByteArray());boolean failure=false;for(ProtoLite.EntityMessage q:f)if(Arrays.equals(q.methodMd5,md5(names[i].replace("request","reply"))))failure=Boolean.FALSE.equals(BsonLite.boolValue(q.parameters,"st"));check(failure,"original typed currency failure");byte[]after=Files.readAllBytes(file);check(value(after,"friendCoin")==0&&value(after,"newFriendCoin")==0&&value(BsonLite.documentValue(after,"ldd"),"q7FriendTotal")==0,"no fee/grant/count after failure");fixture("failure_"+i,f);}
   for(String name:names){boolean newer=name.contains("NewFriend"),ten=name.contains("LianChou");byte[]daily=LocalDrawDailyEngine.refresh(seed(),LocalStoryEnvironment.now());byte[]ldd=BsonLite.documentValue(daily,"ldd");ldd=BsonLite.withProfileInt(ldd,newer?"nfdc":"fdc",ten?91:100);daily=BsonLite.withProfileDocument(daily,"ldd",ldd);LocalResourceEngine.Result capped=LocalFriendDrawEngine.apply(daily,catalog,name,new Random(1));check(Boolean.FALSE.equals(BsonLite.boolValue(reply(capped,name.replace("request","reply")).parameters,"st"))&&Arrays.equals(daily,capped.profile),"stock daily cap rollback "+name);}
   LocalResourceEngine.Result firstTen=LocalFriendDrawEngine.apply(seed(),catalog,names[1],new Random(1));check(Boolean.TRUE.equals(BsonLite.boolValue(reply(firstTen,names[1].replace("request","reply")).parameters,"st"))&&value(firstTen.profile,"friendCoin")==8200,"original first ten charges nine, no artificial currency");
   Path second=dir.resolve("friend_other.bson");Files.write(second,seed());byte[]other=Files.readAllBytes(second);store.updateResources(ACCOUNT,names[0],BsonLite.EMPTY_DOCUMENT);check(Arrays.equals(other,Files.readAllBytes(second)),"other account unchanged");
   Files.write(file,persisted);byte[]committed=Files.readAllBytes(file);Os.failNextRename=true;boolean failed=false;try{store.updateResources(ACCOUNT,names[0],BsonLite.EMPTY_DOCUMENT);}catch(IOException expected){failed=true;}check(failed&&Arrays.equals(committed,Files.readAllBytes(file)),"atomic failure preserves previous BSON");
   gateway.close();System.out.println("FRIEND_ORIGINAL_ENGINE_PASS checks="+checks+"; synthetic BSON, no Android/game/render acceptance");
  }finally{try(java.util.stream.Stream<Path>s=Files.walk(root)){for(Path p:(Iterable<Path>)s.sorted(Comparator.reverseOrder())::iterator)Files.deleteIfExists(p);}}
 }
}
